function minimumSubstringsInPartition(s) {
  const n = s.length;
  const dp = new Array(n + 1).fill(Infinity);
  dp[0] = 0;

  for (let end = 1; end <= n; end++) {
    const count = new Array(26).fill(0);
    let distinct = 0;
    let maxCount = 0;

    for (let start = end - 1; start >= 0; start--) {
      const letter = s.charCodeAt(start) - 97;
      if (count[letter] === 0) {
        distinct++;
      }
      count[letter]++;
      maxCount = Math.max(maxCount, count[letter]);
      if (maxCount * distinct === end - start) {
        dp[end] = Math.min(dp[end], dp[start] + 1);
      }
    }
  }
  return dp[n];
}

