function minimumSubstringsInPartition(s) {
  const balanced = (piece) => {
    const freq = {};
    for (const ch of piece) freq[ch] = (freq[ch] || 0) + 1;
    return new Set(Object.values(freq)).size === 1;
  };
  // Choose the first piece, then solve the rest of the string recursively.
  const memo = new Map();
  const best = (from) => {
    if (from === s.length) return 0;
    if (memo.has(from)) return memo.get(from);
    let result = Infinity;
    for (let to = from + 1; to <= s.length; to++) {
      if (balanced(s.slice(from, to))) result = Math.min(result, 1 + best(to));
    }
    memo.set(from, result);
    return result;
  };
  return best(0);
}

