function generate(rand, size) {
  const pick = (k) => String.fromCharCode(97 + Math.floor(rand() * k));
  if (size === 'small') {
    const n = 1 + Math.floor(rand() * 12);
    const k = 1 + Math.floor(rand() * 4);
    let s = '';
    for (let i = 0; i < n; i++) s += pick(k);
    return [s];
  }
  const n = 1000;
  const mode = Math.floor(rand() * 3);
  let s = '';
  if (mode === 0) {
    const k = 1 + Math.floor(rand() * 26);
    while (s.length < n) s += pick(k);
  } else {
    // Glue together balanced blocks so long balanced pieces exist.
    while (s.length < n) {
      const k = 1 + Math.floor(rand() * (mode === 1 ? 4 : 26));
      const reps = 1 + Math.floor(rand() * 6);
      const letters = [];
      for (let i = 0; i < k; i++) letters.push(pick(26));
      const uniq = [...new Set(letters)];
      const block = [];
      for (const ch of uniq) for (let r = 0; r < reps; r++) block.push(ch);
      for (let i = block.length - 1; i > 0; i--) {
        const j = Math.floor(rand() * (i + 1));
        [block[i], block[j]] = [block[j], block[i]];
      }
      s += block.join('');
      if (rand() < 0.2) s += pick(26);
    }
  }
  return [s.slice(0, n)];
}
